static const struct rasterfall_vmd_bone_track *vmd_track(const struct rasterfall_vmd_clip*c,const char*n){int i;for(i=0;i<c->track_count;i++)if(!strcmp(c->tracks[i].name,n))return &c->tracks[i];return 0;}
static struct rasterfall_animation_quaternion vmd_sample(const struct rasterfall_vmd_bone_track*t,int time,int duration){const struct rasterfall_vmd_keyframe*a,*b;int i,factor=0;struct rasterfall_animation_quaternion q;if(!t||!t->key_count){q.x=q.y=q.z=0;q.w=1;return q;}if(duration>0)time%=duration;a=b=&t->keys[0];for(i=1;i<t->key_count;i++){if(time<t->keys[i].frame*1000/30){b=&t->keys[i];break;}a=&t->keys[i];}if(b!=a&&b->frame>a->frame)factor=(time-a->frame*1000/30)*1000/((b->frame-a->frame)*1000/30);if(a==&t->keys[t->key_count-1]&&duration>0&&time>a->frame*1000/30&&t->key_count>1){int nt=duration;if(nt>a->frame*1000/30)factor=(time-a->frame*1000/30)*1000/(nt-a->frame*1000/30);b=&t->keys[0];}if(factor<0)factor=0;if(factor>1000)factor=1000;return rasterfall_animation_quat_nlerp(a->rotation,b->rotation,factor);}
