int rasterfall_vmd_logic_test(void){struct rasterfall_animation_quaternion q={1,2,3,4};unsigned char curve[64];int linear,curved;memset(curve,0,sizeof(curve));curve[3]=20;curve[7]=8;curve[11]=107;curve[15]=119;linear=rasterfall_animation_vmd_bezier_factor(curve,500);if(linear==500)return 1;curved=rasterfall_animation_vmd_bezier_factor(curve,linear);if(curved<0||curved>1000)return 2;curve[3]=255;if(rasterfall_animation_vmd_bezier_factor(curve,500)!=500)return 3;q=rasterfall_animation_quat_normalize(q);return q.x*q.x+q.y*q.y+q.z*q.z+q.w*q.w<.999||q.x*q.x+q.y*q.y+q.z*q.z+q.w*q.w>1.001?4:0;}
